def ref(arr, k):
    # Obviously-correct model: at most two digits <=> abs value <= 99
    # (single digit 0-9, two digits 10-99, same for negatives ignoring sign)
    return sum(x for x in arr[:k] if abs(x) <= 99)

@given(st.lists(st.integers(min_value=-10000, max_value=10000), min_size=1, max_size=15),
       st.data())
def test_first_k_slicing_property(arr, data):
    k = data.draw(st.integers(min_value=1, max_value=len(arr)))
    # elements beyond k must not affect result
    suffix = data.draw(st.lists(st.integers(min_value=-10000, max_value=10000), min_size=0, max_size=5))
    extended = arr + suffix
    assert add_elements(extended, k) == ref(arr, k)
